if not compiler.query.values_select and self.query.values_select:
    compiler.query = compiler.query.clone()
    # Propagate the requested value fields plus any extra
    # columns that get_order_by() appended to self.select
    # (e.g. ordering columns removed by values_list()).
    select_fields = list(self.query.values_select)
    for sel_expr, _, _ in self.select:
        if hasattr(sel_expr, 'target') and hasattr(sel_expr.target, 'name'):
            if sel_expr.target.name not in select_fields:
                select_fields.append(sel_expr.target.name)
    compiler.query.set_values((
        *self.query.extra_select,
        *select_fields,
        *self.query.annotation_select,
    ))
